#!/usr/bin/env python3
"""Convert one explicitly reviewed public PES head; no automatic name-only assignment or downloads."""
import argparse,importlib.util,json,pathlib,gzip,hashlib,struct
ROOT=pathlib.Path(__file__).resolve().parents[2]
def archive_sha256(path):
 with path.open('rb') as stream:return hashlib.file_digest(stream,'sha256').hexdigest()
def mod(name,file):
 s=importlib.util.spec_from_file_location(name,ROOT/'tools/head-import'/file);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source',type=pathlib.Path,required=True);p.add_argument('--archive',type=pathlib.Path,required=True);p.add_argument('--reader',type=pathlib.Path,required=True);p.add_argument('--stage',type=pathlib.Path,required=True);p.add_argument('--spec',type=pathlib.Path,required=True);p.add_argument('--install',action='store_true');a=p.parse_args();entry=json.loads(a.spec.read_text());manifest_path=ROOT/'assets/heads/manifest.json';manifest=json.loads(manifest_path.read_text());entry['path']='assets/heads/pes/'+entry['sourceId']+'/head.glb.gz';assert not any(e['path']==entry['path'] for e in manifest['players']),'Existing model is never overwritten'
 # Check reviewed identities still exist in the data with this name and birthday.
 reg=json.loads((ROOT/'assets/club-rosters-v75.json').read_text())['teams'];people=[p for c in entry['clubs'] for p in reg.get(c,{}).get('team',{}).get('players',[])+reg.get(c,{}).get('team',{}).get('bench',[])];people.extend(p for f in (ROOT/'assets/player-profiles').glob('*.json') for p in json.loads(f.read_text()).get('players',[]));assert all(any(str(p.get('id'))==i and p['name'] in entry['names'] and p.get('dateOfBirth','')[:10]==entry['dateOfBirth'] for p in people) for i in entry['ids']),'Reviewed game identities changed'
 result=mod('pes_public','convert-pes.py').convert(a.source,a.stage,a.reader,entry['sourceId'],entry['name']);raw=mod('pack_public','pack-glb.py').pack((a.stage/'head.glb').read_bytes());n=struct.unpack_from('<I',raw,12)[0];document=json.loads(raw[20:20+n]);meta=document['extras'];skin=[mat for mat in document['materials'] if mat.get('extras',{}).get('next90Skin')];assert skin and all(mat.get('alphaMode','OPAQUE')=='OPAQUE' for mat in skin),'Opaque source skin is required; reject hair-mask flags on face';data=gzip.compress(raw,compresslevel=9,mtime=0);assert len(data)<2_000_000 and meta['triangles']<35_000;entry.update(result,bytes=len(data),rawBytes=len(raw),triangles=meta['triangles'],sha256=hashlib.sha256(data).hexdigest(),sourceArchiveSHA256=archive_sha256(a.archive));(a.stage/'entry.json').write_text(json.dumps(entry,ensure_ascii=False,indent=2)+'\n')
 if a.install:
  dest=ROOT/entry['path'];assert not dest.exists();dest.parent.mkdir(parents=True,exist_ok=True);temporary=dest.with_suffix('.gz.tmp');temporary.write_bytes(data);temporary.replace(dest);manifest['players'].append(entry);manifest['version']=int((ROOT/'VERSION').read_text().strip().lstrip('vV'));manifest.setdefault('sources',[]).append({'key':entry['source'],'page':entry['sourcePage'],'credit':entry['sourceCredit'],'note':'Explicitly public free attachment; not CC0. Only reviewed compressed model ships.'});temporary=manifest_path.with_suffix('.json.tmp');temporary.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');temporary.replace(manifest_path)
 print(json.dumps({'pass':True,'installed':a.install,'name':entry['name'],'bytes':entry['bytes'],'triangles':entry['triangles'],'sourceId':entry['sourceId']},ensure_ascii=False))
